(()=>{const en=document.documentElement.lang==='en';document.querySelectorAll('[data-image]').forEach(b=>b.addEventListener('click',()=>{const d=document.createElement('dialog');d.className='image-dialog';const close=document.createElement('button');close.textContent=en?'Close ×':'Закрыть ×';const im=document.createElement('img');im.src=b.dataset.image;im.alt=b.querySelector('img')?.alt||'';d.append(close,im);document.body.append(d);d.addEventListener('close',()=>{d.remove();b.focus()});close.onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d)d.close()});d.showModal();close.focus()}));document.querySelectorAll('[data-youtube]').forEach(box=>box.querySelector('button').addEventListener('click',()=>{const frame=document.createElement('iframe');frame.src='https://www.youtube-nocookie.com/embed/'+box.dataset.youtube+'?autoplay=1&rel=0';frame.title=en?'Project animation':'Анимация проекта';frame.allow='autoplay; encrypted-media; picture-in-picture';frame.allowFullscreen=true;box.replaceChildren(frame)}));document.querySelectorAll('.showroom').forEach(root=>{root.addEventListener('loadeddata',()=>{},true);root.querySelectorAll('video').forEach(v=>v.addEventListener('play',()=>{if(!v.muted){const b=root.querySelector('[data-play]');if(b?.getAttribute('aria-pressed')==='true')b.click()}}))});})();
